import collections
def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    q = collections.deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h-1 or c == 0 or c == w-1) and grid[r][c] == bg:
                if (r,c) not in seen:
                    seen.add((r,c)); q.append((r,c))
    while q:
        r,c = q.popleft()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= rr < h and 0 <= cc < w and (rr,cc) not in seen and grid[rr][cc] == bg:
                seen.add((rr,cc)); q.append((rr,cc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r,c) not in seen:
                out[r][c] = 4
    return out
